    ("Id", "ActiveProfileId", "Culture", "Theme", "Palette", "TimeZoneMode", "UtcOffsetMinutes", "QueueCapacity",
     "VisualizerSafeMargin", "CreatedUtc", "ModifiedUtc", "DeletedUtc")
